const cleanArg = (v) => { const t = String(v == null ? '' : v).trim(); return /^\{[a-zA-Z0-9_]+\}$/.test(t) ? '' : t; };
const m = location.pathname.match(/^\/(in|company|showcase|school)\/([^/]+)/);
if (!m) throw new Error('not a LinkedIn person or company page: ' + location.pathname + ' (asked for ' + cleanArg(arg0) + ')');
const to = '/' + m[1] + '/' + m[2] + (m[1] === 'in' ? '/recent-activity/all/' : '/posts/');
setTimeout(() => location.assign(to), 0);
return { to };

const cleanArg = (v) => { const t = String(v == null ? '' : v).trim(); return /^\{[a-zA-Z0-9_]+\}$/.test(t) ? '' : t; };
const LI = { name: 'LinkedIn', id: 'linkedin.com', url: 'https://www.linkedin.com' };
const N = (s) => String(s == null ? '' : s).replace(/ /g, ' ').replace(/[ \t\r\f\v]+/g, ' ').trim();
const compact = (o) => { for (const k of Object.keys(o)) { const v = o[k]; if (v == null || v === '' || (Array.isArray(v) && !v.length) || (typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length)) delete o[k]; } return o; };
const count = (s) => { const m = N(s).replace(/,/g, '').match(/^(\d+(?:\.\d+)?)\s*([KMB])?$/i); return m ? Math.round(Number(m[1]) * ({ K: 1e3, M: 1e6, B: 1e9 }[(m[2] || '').toUpperCase()] || 1)) : null; };
// LinkedIn ids carry their creation time in the top bits (milliseconds since 1970 = id >> 22).
const when = (id) => { try { return new Date(Number(BigInt(id) >> 22n)).toISOString().replace('.000Z', 'Z'); } catch (e) { return null; } };
const fnv = (t) => { let h = 0x811c9dc5; for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193); } return (h >>> 0).toString(16).padStart(8, '0'); };
const URN = /urn:li:(activity|share|ugcPost):(\d+)/;
const CARDS = '.feed-shared-update-v2[data-urn], [role="listitem"][componentkey^="update-card"]';
const BOX = '[data-testid="expandable-text-box"], .update-components-text';
const MORE = /^(…|\.\.\.)\s*(see\s+)?more$/i;
const MENU = 'Open control menu for post by ';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const isMore = (b) => MORE.test(N(b.innerText || b.textContent));
// "… more" shows the rest of a post's text, as a person would click it.
const expand = async () => { let n = 0; for (const b of document.querySelectorAll(CARDS.split(', ').map((c) => c + ' button').join(', '))) { if (isMore(b)) { b.click(); n++; } } if (n) await sleep(1500); };
const textOf = (box) => { const c = box.cloneNode(true); c.querySelectorAll('.visually-hidden, button').forEach((e) => e.remove()); c.querySelectorAll('br').forEach((b) => b.replaceWith('\n')); return c.textContent.split('\n').map(N).join('\n').replace(/\n{3,}/g, '\n\n').trim(); };
const account = (href) => { try { const u = new URL(href, location.origin); const m = u.pathname.match(/^\/(in|company|showcase|school)\/([^/]+)/); return m ? { id: decodeURIComponent(m[2]), url: 'https://www.linkedin.com/' + m[1] + '/' + m[2] + '/' } : null; } catch (e) { return null; } };
const after = (a, b) => !!(a && b && (a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING));
const urnUrl = (type, id) => 'https://www.linkedin.com/feed/update/urn:li:' + type + ':' + id + '/';
const mapCard = (card, forced) => {
  const boxes = [...card.querySelectorAll(BOX)].filter((b, _, all) => !all.some((o) => o !== b && o.contains(b)));
  if (!boxes.length) return null;
  // The author: a company page's card names its actor (the original author, also on a repost);
  // a person's activity list names the author in the post menu.
  const actor = card.querySelector('.update-components-actor__meta-link');
  const menu = card.querySelector('button[aria-label^="' + MENU + '"]');
  const name = actor ? N(((card.querySelector('.update-components-actor__title') || {}).innerText || '').split('\n')[0]) : (menu ? N(menu.getAttribute('aria-label').slice(MENU.length)) : '');
  const links = [...card.querySelectorAll('a[href]')].map((a) => ({ a, who: account(a.getAttribute('href')), label: N(a.getAttribute('aria-label') || a.innerText) })).filter((l) => l.who);
  const own = (actor && links.find((l) => l.a === actor)) || links.find((l) => name && (l.label.startsWith(name) || l.label.startsWith('View: ' + name)));
  if (!own) return null;
  const author = { name: name || own.who.id, id: own.who.id, url: own.who.url };
  // A quoted post sits under the post's own text with its own author; its links are not the post's.
  const quotedBy = boxes.length > 1 ? links.find((l) => l.who.id !== author.id && after(boxes[0], l.a) && !after(boxes[1], l.a)) : null;
  let urn = forced || (card.getAttribute('data-urn') || '').match(URN);
  if (!urn) for (const a of card.querySelectorAll('a[href*="urn:li:"]')) { if (quotedBy && after(quotedBy.a, a)) break; const m = (a.getAttribute('href') || '').match(URN); if (m) { urn = m; break; } }
  if (!urn) return null;
  const [, type, id] = urn;
  const text = textOf(boxes[0]);
  if (!text) return null;
  const blocks = [{ id, kind: 'post', text, at: { order: 0 } }];
  if (quotedBy && boxes[1]) {
    const qt = textOf(boxes[1]);
    const qname = N(((links.find((l) => l.who.id === quotedBy.who.id && N(l.a.innerText)) || quotedBy).a.innerText || '').split('\n')[0]) || quotedBy.who.id;
    if (qt) blocks.push({ id: 'quoted', kind: 'quoted', text: qt, at: { order: 1 }, author: { name: qname, id: quotedBy.who.id, url: quotedBy.who.url } });
  }
  const buttons = [...card.querySelectorAll('button')];
  const metric = (re, plain) => { for (const b of buttons) { const al = b.getAttribute('aria-label') || ''; const m = al.match(re); if (m) return count(m[1]); if (plain.test(al)) { const c = count(b.innerText); if (c != null) return c; } } return null; };
  const collapsed = boxes.some((b) => [...b.querySelectorAll('button')].some(isMore) || / …\s*more$/.test(N(b.textContent)));
  return compact({ type: 'rzn.item/v2', key: 'linkedin:post:' + id, kind: 'post', url: urnUrl(type, id), author, published_at: when(id), published_in: LI,
    marker: 'text:' + fnv(blocks.map((b) => b.text).join('\n')),
    counts: compact({ reactions: metric(/^([\d,.]+\s*[KMB]?) reactions?\b/i, /^Reaction button state/i), comments: metric(/^([\d,.]+\s*[KMB]?) comments?\b/i, /^Comment$/i), reposts: metric(/^([\d,.]+\s*[KMB]?) reposts?\b/i, /^Repost$/i) }),
    blocks, truncated: collapsed ? { reason: 'text_collapsed', returned_blocks: blocks.length } : null });
};

// The account's posts tab as LinkedIn rendered it (its own page; no request of its own). Both page
// styles are read: the activity list of a person (list items) and a company's posts (update cards).
const want = cleanArg(arg0).replace(/^https?:\/\/[^/]+\//, '').replace(/^\/+|\/+$/g, '').split('/').slice(0, 2).join('/');
const owner = (want.match(/^(?:in|company|showcase|school)\/([^/]+)$/) || [])[1];
if (!owner) throw new Error('account must be in/<slug> or company/<slug>, got: ' + cleanArg(arg0));
const cap = 20;
const scroller = document.querySelector('main#workspace');
for (let i = 0, last = -1; i < 6; i++) {
  const n = document.querySelectorAll(CARDS).length;
  if (n >= cap || n === last) break;
  last = n;
  if (scroller && scroller.scrollHeight > scroller.clientHeight + 50) scroller.scrollTo(0, scroller.scrollHeight); else window.scrollTo(0, document.body.scrollHeight);
  await sleep(1800);
}
await expand();
const items = [], seen = new Set();
for (const card of document.querySelectorAll(CARDS)) {
  const item = mapCard(card, null);
  // Reposts are not sent: a card whose author is not the account is someone else's post.
  if (!item || item.author.id.toLowerCase() !== decodeURIComponent(owner).toLowerCase() || seen.has(item.key)) continue;
  seen.add(item.key); items.push(item);
  if (items.length >= cap) break;
}
return { type: 'rzn.items/v2', items, next_cursor: null, listing: 'feed' };
